"""Create the cutoff-only diagnostic after verified, sealed failing contracts."""
import hashlib
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
PHASE = HERE.parent
OLD = PHASE.parent / 'retention-followup'
PACKAGE = Path('org/eclipse/rdf4j/sail/lmdb/evaluation')


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def replace_once(text, old, new):
    if text.count(old) != 1:
        raise ValueError('Expected one source region: ' + old)
    return text.replace(old, new)


def main():
    seal = json.loads((HERE / 'contract-seal-v1.json').read_text())
    for attempt, tests, failures in [('red-small-v1', 1, 1), ('red-all-v1', 12, 3)]:
        record = json.loads((HERE / 'validation' / attempt / 'receipt.json').read_text())
        inputs = json.loads((HERE / 'validation' / attempt / 'inputs.json').read_text())
        if not record['passed'] or record['results'] != dict(tests=tests, failures=failures, errors=0, skipped=0):
            raise ValueError('Required in-repository red evidence is missing')
        if inputs['sources'][seal['testSource']] != seal['sha256']:
            raise ValueError('Red test source differs from the sealed contract')
    if sha(Path(seal['testSource'])) != seal['sha256']:
        raise ValueError('Sealed contract changed')
    target = PHASE / 'implementation-src' / PACKAGE
    target.mkdir(parents=True, exist_ok=False)
    names = ('NativeResultMaterializer.java', 'NativeProjectedBindingSet.java', 'NativeDirectValueMemo.java')
    for name in names:
        text = (OLD / 'implementation-src' / PACKAGE / name).read_text()
        if name == 'NativeDirectValueMemo.java':
            text = replace_once(text, '\tprivate final boolean weakRetention;',
                '\tprivate final boolean weakRetention;\n\tprivate final boolean alwaysAdmit;')
            text = replace_once(text, '\t\tstatisticsOwner = NativeDirectValueMemoStatistics.open();',
                '\t\talwaysAdmit = switch (System.getProperty("rdf4j.lmdb.nativeValueMemo.admission", "initial")) {\n'
                '\t\tcase "initial" -> false;\n\t\tcase "always" -> true;\n'
                '\t\tdefault -> throw new IllegalArgumentException("Unknown native Value memo admission");\n'
                '\t\t};\n\t\tstatisticsOwner = NativeDirectValueMemoStatistics.open();')
            text = replace_once(text, '\t\t\tif (hits < count / 4L) {',
                '\t\t\t// Diagnostic ablation: all growth and ownership decisions remain unchanged.\n'
                '\t\t\tif (!alwaysAdmit && hits < count / 4L) {')
        (target / name).write_text(text)
    receipt = {'redSealSha256': sha(HERE / 'contract-seal-v1.json'),
               'unchangedOwnershipSources': list(names[:2]),
               'sources': {str(p): sha(p) for p in sorted(target.glob('*.java'))}}
    with (HERE / 'source-generation-v1.json').open('x') as out:
        json.dump(receipt, out, indent=2)
        out.write('\n')
    print('Created three complete sources; only NativeDirectValueMemo has a behavior change.')


if __name__ == '__main__':
    main()
